/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field TAMRebateReference
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeSalesTableTAMRebateReference extends UPSPricingAttributeSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, TAMRebateReference);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    SalesTable salesTable;
    while select TAMRebateReference from salesTable
        group by TAMRebateReference
    {
        ret.add(salesTable.TAMRebateReference);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, TAMRebateReference));
    qbr.value(queryValue(_value));
}
